sequence.script:
mc.setProperty("jwt_empr_id", "");
mc.setProperty("jwt_mysql_empresa_id", "");
try {
    var assertion = mc.getProperty("x_jwt_assertion");
    if (assertion) {
        var parts = ("" + assertion).split(".");
        if (parts.length === 3) {
            var bytes   = Packages.java.util.Base64.getUrlDecoder().decode(parts[1]);
            var payload = JSON.parse("" + new Packages.java.lang.String(bytes, "UTF-8"));
            if (payload.empr_id || payload.empr_id === 0) {
                mc.setProperty("jwt_empr_id", "" + payload.empr_id);
            }
            if (payload.empr_id_mysql || payload.empr_id_mysql === 0) {
                mc.setProperty("jwt_mysql_empresa_id", "" + payload.empr_id_mysql);
            }
        }
    }
} catch (e) {
    mc.setProperty("dbg_err", "" + e);
}
